              "emotional_shift": "开门时的紧张→倒药时的决绝→冲完水后的病态轻松",
              "scene_outcome": "沈砚锁好药房门悄无声息回到病房，完全没注意到走廊的监控摄像头刚好拍下了他的所有动作"
            }
          ]
        }
      ]
    },
    {
      "act_name": "第三幕：双向毁灭",
      "turning_point": "陈默故意把监控录像放在苏晚病房，苏晚看完后恢复了全部记忆，知晓所有真相",
      "chapters": [
        {
          "chapter_number": 3,
          "chapter_synopsis": "陈默发现解药被销毁，故意把监控录像放在苏晚床头，苏晚看完录像又找到沈砚藏在床垫下的合照和日记，所有记忆全部恢复。她和沈砚对峙，沈砚哭着承认所有事求她原谅，苏晚说她的爱情不该是被囚禁的，从窗户跳了下去。沈砚崩溃后被陈默注射镇定剂，当成新的实验样本永远困在精神病院，每天重复过去的流程。",
          "scene_sequence": [
            {
              "scene_number": 1,
              "scene_location": "苏晚的病房",
              "characters_present": ["苏晚"],
