                      "type": "string"
                    },
                    "emotional_shift": {
                      "type": "string"
                    },
                    "scene_outcome": {
                      "type": "string"
                    }
                  }
                }
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章整体情感基调"
              }
            }
          }
        },
